import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.UjrY2eRK.js";const g=JSON.parse('{"title":"Organize future applications with Nx","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr/0020-organize-future-applications-with-nx.md","filePath":"architecture/adr/0020-organize-future-applications-with-nx.md","lastUpdated":1788123021000}'),o={name:"architecture/adr/0020-organize-future-applications-with-nx.md"};function r(s,e,c,d,p,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="organize-future-applications-with-nx" tabindex="-1">Organize future applications with Nx <a class="header-anchor" href="#organize-future-applications-with-nx" aria-label="Permalink to &quot;Organize future applications with Nx&quot;">​</a></h1><p>The repository will use an Nx 23 workspace with root-managed pnpm dependencies. The existing Cloudflare Worker and Bun deployment remain one <code>push-gateway</code> application under <code>apps/push-gateway</code> because they implement one Push Gateway contract and release together. A tracked <code>apps/push-gateway-ui</code> placeholder reserves the name and location of a future Angular administration application without introducing Angular dependencies, project metadata, an administration API, authentication design, or UI code.</p><p>Official Nx ESLint and Vitest plugins infer project-scoped <code>lint</code> and run-mode <code>test</code> targets. Nx Core exposes explicit targets for Wrangler, Bun, TypeScript, migration, coverage, bundle-policy, and aggregate commands because the specialized plugins are absent, deprecated, or do not preserve the runtime contract. Deterministic validation and filesystem build outputs use the local Nx cache; fixing lint, development servers, migrations, deployment, releases, and Docker-daemon state do not. CI uses affected execution immediately, keeps required check names visible as successful no-ops when the gateway is unaffected, and treats shared dependencies, workspace configuration, Compose, and CI configuration as gateway-affecting. Nx Cloud, Nx Release, Nx Docker, and premature Angular integration remain excluded; Release Please continues to own versioning, changelog generation, tags, and stable releases.</p><p>Gateway-owned source, tests, migrations, runtime configuration, and the Dockerfile live within <code>apps/push-gateway</code>. The root retains workspace tooling, root-managed dependencies, Compose, CI, documentation, and release configuration. Build artifacts live under <code>dist/apps/push-gateway</code>, coverage under <code>coverage/apps/push-gateway</code>, and internal gateway imports remain relative. This structure creates a real future application boundary without splitting the Worker and Bun adapters into artificial projects.</p>',4)])])}const h=a(o,[["render",r]]);export{g as __pageData,h as default};
